function blockedLeafResult(materialHash: string, reason: string, summary: string): CodexReviewLeafResult {
  return {
    hostBVerdict: synthesizedBlocked(materialHash, reason, summary),
    stdoutDigest: digest(''),
    exitCode: HOST_RUN_REFUSAL_EXIT_CODE,
    timedOut: false,
  };
}

/**
 * Run the read-only Codex review leaf and return a validated, materialHash-bound
 * verdict. FAIL-CLOSED:
 *   - no parseable/schema-valid verdict → decision 'blocked', reason
 *     `codex_review_no_parseable_verdict`;
 *   - verdict.materialHash !== opts.materialHash (a rebinding attempt / stale
 *     tree) → decision 'blocked', reason `codex_review_material_mismatch`.
 * Never returns raw stdout — only a stdoutDigest for provenance.
 */
export async function runCodexReviewLeaf(
  opts: RunCodexReviewLeafOptions,
  runner: CodexReviewRunner = defaultCodexReviewRunner,
): Promise<CodexReviewLeafResult> {
  const prompt = buildCodexReviewPrompt({
    storyId: opts.storyId,
    materialHash: opts.materialHash,
    ...(opts.hostAFindings ? { hostAFindings: opts.hostAFindings } : {}),
  });

  // B-70e9 CHK-003: usage-ledger preflight over the review prompt (fail-open; strict
  // no-op when the ledger is OFF or no binding was supplied). The codex argv below is
  // untouched — this only makes the spawn visible in the ledger.
  const ledger = opts.usageLedger;
  const ledgerOn = ledger !== undefined && isUsageLedgerEnabled(ledger.env);
  let ledgerCtx: DispatchUsageContext | null = null;
  let ledgerOpts: DispatchUsageOptions | null = null;
  let ledgerHandle: DispatchPreflightHandle | null = null;
  // Provider admission is ledger-independent. The usage budget below remains
  // ledger-bound, but no diagnostic toggle may bypass the shared spawn cap.
  let admissionSlot: AcquiredProviderProcessSlot | null = null;
  if (ledgerOn && ledger) {
    ledgerCtx = {
      storyId: opts.storyId,
      phase: ledger.phase,
      agentType: CROSS_HOST_REVIEW_CODEX_AGENT_TYPE,
    };
    ledgerOpts = {
      recordedAt: ledger.recordedAt,
      projectRootHash: ledger.projectRootHash,
      command: CROSS_HOST_REVIEW_CODEX_COMMAND,
      host: { kind: 'codex' },
      env: ledger.env,
    };
    try {
      ledgerHandle = recordDispatchPreflight(ledger.root, ledgerCtx, prompt, ledgerOpts);
    } catch {
      ledgerHandle = null;
    }

    // F-017: the codex review leaf is a lattice-initiated host spawn, so — AFTER
    // the preflight and BEFORE the runner — it passes the SAME pre-spawn
    // admission as runHostRun / the autopilot repair (budget -> concurrency ->
    // spawn). A refusal records the appropriate blocked ledger row and returns a
    // SYNTHESIZED fail-closed 'blocked' verdict WITHOUT invoking the runner, so
    // cross_host_review yields hostB decision 'blocked' (never a fabricated
    // 'pass'/'fail') and a jointDecision 'blocked'. Budget admission is ledger-
    // backed; provider capacity admission below remains mandatory in both ledger
    // modes. Turning diagnostics off must never bypass the spawn cap.
    //
    // (1) Hard-budget admission (fail-closed; the blocked row is written inside
    // recordBudgetBlock, which never throws). A codex review leaf is a codex
    // launch, so the openai provider binding mirrors host_run's codex path.
    const budget = recordBudgetBlock(ledger.root, ledgerCtx, ledgerHandle, prompt, ledgerOpts, { name: 'openai', model: null });
    if (budget.blocked) {
      return blockedLeafResult(
        opts.materialHash,
        CODEX_REVIEW_BUDGET_BLOCKED,
        `Codex review leaf refused pre-spawn: hard_budget_exceeded (${budget.budgetPolicyId ?? 'hard-budget'}${
          budget.hardBudgetTokens !== null ? `, cap ${budget.hardBudgetTokens}` : ''
        }); the codex runner was never invoked.`,
      );
    }
  }

  if (!opts.managedExecution) {
    // (2) Concurrency admission via the SAME atomic fixed-slot registry as
    // host_run: acquire before the spawn, release in the finally below. On a cap
    // refusal, record the concurrency blocked row and return WITHOUT spawning. A
    // slot-registry error also refuses fail-closed (an admission error must never
    // grant an unguarded spawn) but does NOT fabricate a concurrency_cap_exceeded
    // row for a refusal that was not a cap decision — same doctrine as F-016.
    const admissionRoot = ledger?.root ?? opts.storyWorktree;
    const admissionEnv = ledger?.env ?? opts.env ?? process.env;
    const cap = resolveMaxConcurrent(admissionEnv);
    let registryError: string | null = null;
    try {
      admissionSlot = acquireProviderProcessSlot(providerProcessSlotsDir(admissionRoot), cap, resolveSlotStaleMs(admissionEnv), Date.now(), {
        pid: process.pid,
        startedAt: ledger?.recordedAt ?? new Date().toISOString(),
    lines.push('status=SHADOW_RECORDED');
  }
  lines.push(`ambiguity=${artifact.ambiguitySignals.join(',') || 'none'}`);
  lines.push(`scanEscalationReason=${artifact.scanEscalationReason ?? 'null'}`);
  lines.push(...artifact.candidates.map((candidate, index) => `${index + 1}. ${candidate.path} score=${candidate.score}`));
  return lines.join('\n');
}

function changedPaths(ctx: HandlerContext, storyId: string): string[] {
  try {
    const gitCwd = resolveGitCwd({
      store: ctx.store,
      storyId,
      metadataRoot: ctx.root,
      projectRoot: ctx.root,
    });
    return execFileSync('git', ['diff', '--name-only', 'main...HEAD'], { cwd: gitCwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })
      .split(/\r?\n/)
      .map(value => value.trim())
      .filter(path => Boolean(path) && !isStoryMetadataPath(path, ctx.root))
      .sort();
  } catch {
    return [];
  }
}

function parseProposalOutput(text: string): unknown {
  const trimmed = text.trim();
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(trimmed)?.[1]?.trim();
  for (const candidate of [fenced, trimmed].filter((value): value is string => Boolean(value))) {
    try { return JSON.parse(candidate); } catch { /* try bounded object below */ }
  }
  const start = trimmed.indexOf('{');
  const end = trimmed.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(trimmed.slice(start, end + 1));
  throw new Error('host proposal output did not contain a JSON object');
}

/**
 * Bounded final proposal lane shared by the production passthrough and its
 * executable boundary smoke. Overflow invalidates the entire candidate stream:
 * a parseable prefix is never accepted after later bytes exceed the cap.
 */
export class CandidateProposalOutputCollector {
  private output = '';
  private overflow = false;

  push(text: string): void {
    if (this.overflow) return;
    if (Buffer.byteLength(this.output) + Buffer.byteLength(text) > MAX_PROPOSAL_OUTPUT_BYTES) {
      this.overflow = true;
      this.output = '';
      return;
    }
    this.output += text;
  }

  finish(result: Pick<HostRunResult,
    'blocked' | 'refusalReason' | 'timedOut' | 'timeoutKind' | 'firstOutputMs' | 'durationMs' | 'exitCode' | 'terminalReason' | 'failureKind'>): unknown {
    const failureReason = candidateHostFailureReason(result);
    if (failureReason) throw new Error(failureReason);
    if (this.overflow) throw new Error('host proposal output budget exceeded');
    if (result.firstOutputMs === null) throw new Error('post_readiness_no_output');
    return parseProposalOutput(this.output);
  }
}

// B-137a:F-122 — exhaustive, no silent fallback. The previous form returned
// 'agy' for anything that was not codex/claude, so a future host added to the
// union would have been silently mislabeled as agy rather than failing to
// compile. The union no longer contains 'agy-cli' (its construction site was
// deleted), and the `never` check now makes any new host a compile error here.
function hostName(host: HostKeywordProposal['host']): 'codex' | 'claude' {
  if (host === 'codex-cli') return 'codex';
  if (host === 'claude-cli') return 'claude';
  const unreachable: never = host;
  throw new Error(`unsupported candidate-spec routing host: ${String(unreachable)}`);
